var n=`1064-hainanese-chicken-rice`;var s=`world-1064`;var a=`SG`;var t=`southeast-asia`;var o=4;var r=89;var c={en:`Hainanese Chicken Rice`,ua:`Хайнаньський рис із куркою`};var l={en:`Hainanese Chicken Rice is a dish from Singapore prepared with whole chicken, green onion, jasmine rice, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Хайнаньський рис із куркою, страва кухні країни Сінгапур, яку готують із таких продуктів: ціла курка, зелена цибуля, рис жасмин, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 55 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 55 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:55,i:[[`whole-chicken`,1200,`g`],[`water`,2100,`ml`],[`ground-ginger`,75,`g`],[`green-onion`,65,`g`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 23 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 23 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:23,i:[[`jasmine-rice`,450,`g`],[`chicken-stock`,760,`ml`],[`chicken-schmaltz`,35,`g`],[`garlic`,4,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`ground-ginger`,30,`g`],[`serrano-pepper`,2,`pcs`],[`lime-juice`,35,`ml`],[`light-soy-sauce`,35,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`cucumber`,220,`g`],[`cilantro`,30,`g`]]}];var m={slug:n,id:s,country:`SG`,region:t,servings:4,minutes:89,title:c,text:l,steps:g};export{a as country,m as default,s as id,r as minutes,t as region,o as servings,n as slug,g as steps,l as text,c as title};